beforeExample:
class MyClass {
    void printLine() {
        StringBuilder buffer = new StringBuilder();
        buffer.append("Hello");
        buffer.append(System.getProperty("line.separator"));
        System.out.println(buffer.toString());
    }
}

afterExample:
class MyClass {
    void printLine() {
        StringBuilder buffer = new StringBuilder();
        buffer.append("Hello");
        buffer.append(System.lineSeparator());
        System.out.println(buffer.toString());
    }
}

